use std::fmt::Write as _;
use std::io::{self, Write};
use std::process::ExitCode;

use wgpu::util::DeviceExt;

const WORKGROUP: u32 = 16;

/// One heat step. Reads `src`, writes `dst`; the two buffers are swapped each step.
const SHADER: &str = r#"
struct Params {
    width: u32,
    height: u32,
}

@group(0) @binding(0) var<storage, read> src: array<u32>;
@group(0) @binding(1) var<storage, read_write> dst: array<u32>;
@group(0) @binding(2) var<uniform> params: Params;

@compute @workgroup_size(16, 16)
fn step(@builtin(global_invocation_id) id: vec3<u32>) {
    let x = id.x;
    let y = id.y;
    let w = params.width;
    let h = params.height;
    if (x >= w || y >= h) {
        return;
    }

    var xl = x;
    if (x > 0u) {
        xl = x - 1u;
    }
    var xr = x;
    if (x + 1u < w) {
        xr = x + 1u;
    }
    var yu = y;
    if (y > 0u) {
        yu = y - 1u;
    }
    var yd = y;
    if (y + 1u < h) {
        yd = y + 1u;
    }

    let centre = src[y * w + x];
    let left = src[y * w + xl];
    let right = src[y * w + xr];
    let up = src[yu * w + x];
    let down = src[yd * w + x];

    dst[y * w + x] = (4u * centre + left + right + up + down) / 8u;
}
"#;

struct Grid {
    width: u32,
    height: u32,
    steps: u32,
    cells: Vec<u32>,
}

fn parse(text: &str) -> Result<Grid, String> {
    let mut tokens = text.split_ascii_whitespace();
    let mut next = |what: &str| -> Result<u64, String> {
        let tok = tokens
            .next()
            .ok_or_else(|| format!("input ends before {what}"))?;
        tok.parse::<u64>()
            .map_err(|_| format!("invalid {what}: {tok:?}"))
    };

    let width = next("width")?;
    let height = next("height")?;
    let steps = next("steps")?;
    if !(1..=512).contains(&width) || !(1..=512).contains(&height) {
        return Err(format!("dimensions out of range: {width}x{height}"));
    }
    if steps > 1000 {
        return Err(format!("steps out of range: {steps}"));
    }

    let count = (width * height) as usize;
    let mut cells = Vec::with_capacity(count);
    for _ in 0..count {
        let v = next("cell value")?;
        if v > 1_000_000 {
            return Err(format!("cell value out of range: {v}"));
        }
        cells.push(v as u32);
    }

    Ok(Grid {
        width: width as u32,
        height: height as u32,
        steps: steps as u32,
        cells,
    })
}

async fn run_gpu(grid: &Grid) -> Result<Vec<u32>, String> {
    let instance = wgpu::Instance::new(wgpu::InstanceDescriptor::new_without_display_handle());
    let adapter = instance
        .request_adapter(&wgpu::RequestAdapterOptions {
            power_preference: wgpu::PowerPreference::HighPerformance,
            force_fallback_adapter: false,
            compatible_surface: None,
        })
        .await
        .map_err(|e| format!("no GPU adapter available: {e}"))?;
    let (device, queue) = adapter
        .request_device(&wgpu::DeviceDescriptor::default())
        .await
        .map_err(|e| format!("could not create GPU device: {e}"))?;

    let size = (grid.cells.len() * std::mem::size_of::<u32>()) as wgpu::BufferAddress;
    let storage_usage = wgpu::BufferUsages::STORAGE
        | wgpu::BufferUsages::COPY_SRC
        | wgpu::BufferUsages::COPY_DST;

    let buf_a = device.create_buffer_init(&wgpu::util::BufferInitDescriptor {
        label: Some("grid a"),
        contents: bytemuck::cast_slice(&grid.cells),
        usage: storage_usage,
    });
    let buf_b = device.create_buffer(&wgpu::BufferDescriptor {
        label: Some("grid b"),
        size,
        usage: storage_usage,
        mapped_at_creation: false,
    });
    let params = [grid.width, grid.height, 0, 0];
    let params_buf = device.create_buffer_init(&wgpu::util::BufferInitDescriptor {
        label: Some("params"),
        contents: bytemuck::cast_slice(&params),
        usage: wgpu::BufferUsages::UNIFORM,
    });

    let shader = device.create_shader_module(wgpu::ShaderModuleDescriptor {
        label: Some("heat"),
        source: wgpu::ShaderSource::Wgsl(SHADER.into()),
    });
    let layout = device.create_bind_group_layout(&wgpu::BindGroupLayoutDescriptor {
        label: Some("heat layout"),
        entries: &[
            storage_entry(0, true),
            storage_entry(1, false),
            wgpu::BindGroupLayoutEntry {
                binding: 2,
                visibility: wgpu::ShaderStages::COMPUTE,
                ty: wgpu::BindingType::Buffer {
                    ty: wgpu::BufferBindingType::Uniform,
                    has_dynamic_offset: false,
                    min_binding_size: None,
                },
                count: None,
            },
        ],
    });
    let pipeline_layout = device.create_pipeline_layout(&wgpu::PipelineLayoutDescriptor {
        label: Some("heat pipeline layout"),
        bind_group_layouts: &[Some(&layout)],
        immediate_size: 0,
    });
    let pipeline = device.create_compute_pipeline(&wgpu::ComputePipelineDescriptor {
        label: Some("heat step"),
        layout: Some(&pipeline_layout),
        module: &shader,
        entry_point: Some("step"),
        compilation_options: Default::default(),
        cache: None,
    });

    // bind_groups[0]: read a, write b. bind_groups[1]: read b, write a.
    let bind_group = |src: &wgpu::Buffer, dst: &wgpu::Buffer| {
        device.create_bind_group(&wgpu::BindGroupDescriptor {
            label: Some("heat bind group"),
            layout: &layout,
            entries: &[
                wgpu::BindGroupEntry {
                    binding: 0,
                    resource: src.as_entire_binding(),
                },
                wgpu::BindGroupEntry {
                    binding: 1,
                    resource: dst.as_entire_binding(),
                },
                wgpu::BindGroupEntry {
                    binding: 2,
                    resource: params_buf.as_entire_binding(),
                },
            ],
        })
    };
    let bind_groups = [bind_group(&buf_a, &buf_b), bind_group(&buf_b, &buf_a)];

    let mut encoder = device.create_command_encoder(&wgpu::CommandEncoderDescriptor {
        label: Some("heat encoder"),
    });
    let groups_x = grid.width.div_ceil(WORKGROUP);
    let groups_y = grid.height.div_ceil(WORKGROUP);
    for step in 0..grid.steps as usize {
        // Each step is its own compute pass so the previous step's writes are visible to it.
        let mut pass = encoder.begin_compute_pass(&wgpu::ComputePassDescriptor {
            label: Some("heat step pass"),
            timestamp_writes: None,
        });
        pass.set_pipeline(&pipeline);
        pass.set_bind_group(0, &bind_groups[step % 2], &[]);
        pass.dispatch_workgroups(groups_x, groups_y, 1);
    }

    // After an even number of steps the result is back in buf_a.
    let result = if grid.steps % 2 == 0 { &buf_a } else { &buf_b };
    let readback = device.create_buffer(&wgpu::BufferDescriptor {
        label: Some("readback"),
        size,
        usage: wgpu::BufferUsages::MAP_READ | wgpu::BufferUsages::COPY_DST,
        mapped_at_creation: false,
    });
    encoder.copy_buffer_to_buffer(result, 0, &readback, 0, size);
    queue.submit(Some(encoder.finish()));

    let slice = readback.slice(..);
    let (tx, rx) = std::sync::mpsc::channel();
    slice.map_async(wgpu::MapMode::Read, move |r| {
        let _ = tx.send(r);
    });
    device
        .poll(wgpu::PollType::wait_indefinitely())
        .map_err(|e| format!("GPU poll failed: {e}"))?;
    rx.recv()
        .map_err(|e| format!("readback channel closed: {e}"))?
        .map_err(|e| format!("readback failed: {e}"))?;

    let data = slice.get_mapped_range();
    let out: Vec<u32> = bytemuck::cast_slice(&data).to_vec();
    drop(data);
    readback.unmap();
    Ok(out)
}

fn storage_entry(binding: u32, read_only: bool) -> wgpu::BindGroupLayoutEntry {
    wgpu::BindGroupLayoutEntry {
        binding,
        visibility: wgpu::ShaderStages::COMPUTE,
        ty: wgpu::BindingType::Buffer {
            ty: wgpu::BufferBindingType::Storage { read_only },
            has_dynamic_offset: false,
            min_binding_size: None,
        },
        count: None,
    }
}

fn report(width: usize, cells: &[u32]) -> io::Result<()> {
    let mut out = String::with_capacity(cells.len() * 8);
    let mut sum: u64 = 0;
    for row in cells.chunks(width) {
        for (i, v) in row.iter().enumerate() {
            if i > 0 {
                out.push(' ');
            }
            let _ = write!(out, "{v}");
            sum += u64::from(*v);
        }
        out.push('\n');
    }
    let _ = writeln!(out, "SUM {sum}");
    let mut stdout = io::stdout().lock();
    stdout.write_all(out.as_bytes())?;
    stdout.flush()
}

fn main() -> ExitCode {
    let Some(path) = std::env::args().nth(1) else {
        eprintln!("usage: heat <input-file>");
        return ExitCode::FAILURE;
    };
    let text = match std::fs::read_to_string(&path) {
        Ok(t) => t,
        Err(e) => {
            eprintln!("cannot read {path}: {e}");
            return ExitCode::FAILURE;
        }
    };
    let grid = match parse(&text) {
        Ok(g) => g,
        Err(e) => {
            eprintln!("bad input: {e}");
            return ExitCode::FAILURE;
        }
    };
    let cells = match pollster::block_on(run_gpu(&grid)) {
        Ok(c) => c,
        Err(e) => {
            eprintln!("{e}");
            return ExitCode::FAILURE;
        }
    };
    match report(grid.width as usize, &cells) {
        Ok(()) => ExitCode::SUCCESS,
        Err(e) => {
            eprintln!("cannot write output: {e}");
            ExitCode::FAILURE
        }
    }
}

